package cuemap

import (
	"encoding/json"
	"os"
)

// Fixture is one generated test material case.
type Fixture struct {
	Name    string  `json:"name"`
	Cue     Cue     `json:"cue"`
	Options Options `json:"options"`
	WantOK  bool    `json:"want_ok"`
}

// FixtureFile is the on-disk JSON envelope generated by cmd/genfixtures.
type FixtureFile struct {
	Schema    string    `json:"schema"`
	Generator string    `json:"generator"`
	Fixtures  []Fixture `json:"fixtures"`
}

// LoadFixtures reads a stdlib-generated JSON fixture file.
func LoadFixtures(path string) (FixtureFile, error) {
	var file FixtureFile
	data, err := os.ReadFile(path)
	if err != nil {
		return file, err
	}
	if err := json.Unmarshal(data, &file); err != nil {
		return file, err
	}
	return file, nil
}

// WriteFixtures writes fixtures as indented JSON.
func WriteFixtures(path string, file FixtureFile) error {
	data, err := json.MarshalIndent(file, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return os.WriteFile(path, data, 0o644)
}
